import { loadFont } from "@remotion/google-fonts/Montserrat";
import React from "react";
import { AbsoluteFill, Easing, OffthreadVideo, Sequence, interpolate, spring, staticFile, useCurrentFrame } from "remotion";

// AR Estúdio (com E, corrigido em 29/10) · 2º vídeo: oferta "10 vídeos comerciais por R$ 587,00, só para 10 empresas de Águas Claras" (28/10).
// Mesma identidade do vídeo do estúdio (azul do LED, fundo escuro, lilás, Montserrat), mas outra abertura e outro fio:
// a grade com 10 vídeos do próprio estúdio (os "10 vídeos" do pacote) abre o vídeo, volta na conta dos R$ 58,70 e vira
// as 10 vagas. Cenas desenhadas intercaladas com os vídeos do estúdio (pedido: mais motion entre as imagens).
// Tempos = voz-oferta-v1-apertada.wav ((arquivo do cliente)). Sem áudio aqui.

const { fontFamily: F } = loadFont("normal", { weights: ["600", "700", "800", "900"], subsets: ["latin", "latin-ext"] });

export const AROF_FPS = 30;
const END = 45.2;
export const AROF_FRAMES = Math.round(END * AROF_FPS);

const BLUE = "#2F3DFF";
const NAVY = "#070A24";
const PANEL = "#10154A";
const LILAC = "#AEB8FF";
const RED = "#FF3B3B";
const COL = 840;

const cl = { extrapolateLeft: "clamp", extrapolateRight: "clamp" } as const;
const OUT = Easing.bezier(0.16, 1, 0.3, 1);
const IN_OUT = Easing.bezier(0.65, 0, 0.35, 1);
const k = (t: number, a: number, d = 0.45, e = OUT) => interpolate(t, [a, a + d], [0, 1], { ...cl, easing: e });
const sp = (t: number, a: number, damping = 18, stiffness = 120) =>
  t < a ? 0 : spring({ frame: (t - a) * AROF_FPS, fps: AROF_FPS, config: { damping, stiffness } });

const Rise: React.FC<{ t: number; at: number; size: number; color?: string; weight?: number; children: React.ReactNode; ls?: string }> = ({ t, at, size, color = "#FFFFFF", weight = 900, children, ls = "-0.01em" }) => {
  const e = sp(t, at, 20, 140);
  return (
    <div style={{ overflow: "hidden", paddingBottom: size * 0.04 }}>
      <div style={{ fontFamily: F, fontWeight: weight, fontSize: size, lineHeight: 1.08, letterSpacing: ls, color, whiteSpace: "nowrap", textAlign: "center", transform: `translateY(${((1 - e) * 110).toFixed(1)}%)` }}>{children}</div>
    </div>
  );
};

const Ico: React.FC<{ d: string[]; size: number; color?: string; fill?: boolean; sw?: number }> = ({ d, size, color = "#FFFFFF", fill, sw = 2 }) => (
  <svg width={size} height={size} viewBox="0 0 24 24" fill={fill ? color : "none"} stroke={fill ? "none" : color} strokeWidth={sw} strokeLinecap="round" strokeLinejoin="round">
    {d.map((p, i) => <path key={i} d={p} />)}
  </svg>
);
const I_PIN = ["M12 2a7 7 0 0 0-7 7c0 5.2 7 13 7 13s7-7.8 7-13a7 7 0 0 0-7-7zm0 9.6a2.6 2.6 0 1 1 0-5.2 2.6 2.6 0 0 1 0 5.2z"];
const I_HEART = ["M19 14c1.49-1.46 3-3.21 3-5.5A5.5 5.5 0 0 0 16.5 3c-1.76 0-3 .5-4.5 2-1.5-1.5-2.74-2-4.5-2A5.5 5.5 0 0 0 2 8.5c0 2.3 1.5 4.05 3 5.5l7 7Z"];
const I_CHAT = ["M21 11.5a8.4 8.4 0 0 1-12.2 7.5L3 21l2-5.6A8.4 8.4 0 1 1 21 11.5z"];
const I_SEND = ["M22 2 11 13", "M22 2l-7 20-4-9-9-4z"];
const I_DOC = ["M14 2H6a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V8z", "M14 2v6h6", "M8 13h8", "M8 17h6"];
const I_CAM = ["M23 7l-7 5 7 5V7z", "M3 5h11a2 2 0 0 1 2 2v10a2 2 0 0 1-2 2H3a2 2 0 0 1-2-2V7a2 2 0 0 1 2-2z"];
const I_CUT = ["M6 9a3 3 0 1 0 0-6 3 3 0 0 0 0 6z", "M6 21a3 3 0 1 0 0-6 3 3 0 0 0 0 6z", "M20 4 8.1 15.9", "M14.5 14.5 20 20", "M8.1 8.1 12 12"];
const I_CHECK = ["M5 12.5l4.5 4.5L19 7.5"];

// os 10 vídeos do pacote: trechos do próprio estúdio
const TILES = ["c03.mp4", "c05.mp4", "c06.mp4", "c07.mp4", "c09.mp4", "c10.mp4", "c12.mp4", "c13.mp4", "c14.mp4", "c15.mp4"];
const Tile: React.FC<{ f: string; w: number; h: number; from: number }> = ({ f, w, h, from }) => (
  <div style={{ width: w, height: h, borderRadius: 18, overflow: "hidden", background: PANEL }}>
    <Sequence from={Math.round(from * AROF_FPS)} layout="none">
      <OffthreadVideo src={staticFile(`ar-estudio/${f}`)} muted style={{ width: "100%", height: "100%", objectFit: "cover" }} />
    </Sequence>
  </div>
);

// ───────── camadas ─────────
type Enter = "cut" | "push" | "zoom" | "wipe" | "up" | "flood";
type Move = "in" | "out" | "left" | "right";
type Layer = { a: number; b: number; enter: Enter; move?: Move; f?: string; M?: React.FC<{ t: number; a: number; b: number }>; ox?: number; oy?: number };

const Frame: React.FC<{ t: number; L: Layer; children: React.ReactNode }> = ({ t, L, children }) => {
  const e = L.enter === "cut" ? 1 : k(t, L.a, L.enter === "flood" ? 0.55 : 0.42, IN_OUT);
  let wrap: React.CSSProperties = {};
  let extra = 1;
  if (L.enter === "push") wrap = { transform: `translateX(${((1 - e) * 1080).toFixed(1)}px)` };
  if (L.enter === "up") wrap = { transform: `translateY(${((1 - e) * 1920).toFixed(1)}px)` };
  if (L.enter === "wipe") wrap = { clipPath: `inset(0 0 0 ${((1 - e) * 100).toFixed(2)}%)` };
  if (L.enter === "flood") wrap = { clipPath: `circle(${(e * 160).toFixed(1)}% at ${L.ox ?? 50}% ${L.oy ?? 72}%)` };
  if (L.enter === "zoom") {
    extra = 1 + 0.22 * (1 - e);
    wrap = { opacity: Math.min(1, e * 2), filter: e < 1 ? `blur(${((1 - e) * 14).toFixed(1)}px)` : undefined };
  }
  return (
    <AbsoluteFill style={{ overflow: "hidden", background: NAVY, ...wrap }}>
      <AbsoluteFill style={{ transform: `scale(${extra.toFixed(4)})` }}>{children}</AbsoluteFill>
    </AbsoluteFill>
  );
};

const Footage: React.FC<{ t: number; L: Layer }> = ({ t, L }) => {
  const u = interpolate(t, [L.a, L.b], [0, 1], cl);
  const z = L.move === "in" ? 1.02 + 0.07 * u : L.move === "out" ? 1.09 - 0.07 * u : 1.07;
  const dx = L.move === "left" ? (0.5 - u) * 50 : L.move === "right" ? (u - 0.5) * 50 : 0;
  return (
    <>
      <AbsoluteFill style={{ transform: `scale(${z.toFixed(4)}) translateX(${dx.toFixed(1)}px)` }}>
        <Sequence from={Math.round(L.a * AROF_FPS)} layout="none">
          <OffthreadVideo src={staticFile(`ar-estudio/${L.f}`)} muted style={{ width: "100%", height: "100%", objectFit: "cover" }} />
        </Sequence>
      </AbsoluteFill>
      <AbsoluteFill style={{ background: "linear-gradient(180deg, rgba(4,6,24,0.35) 0px, rgba(4,6,24,0) 340px, rgba(4,6,24,0) 950px, rgba(4,6,24,0.5) 1250px, rgba(4,6,24,0.85) 1920px)" }} />
    </>
  );
};

const Cam: React.FC<{ t: number; a: number; b: number; from?: number; to?: number; children: React.ReactNode }> = ({ t, a, b, from = 1.0, to = 1.07, children }) => {
  const u = interpolate(t, [a - 0.2, b + 0.4], [0, 1], cl);
  return <AbsoluteFill style={{ alignItems: "center", justifyContent: "center", transform: `scale(${(from + (to - from) * u).toFixed(4)})` }}>{children}</AbsoluteFill>;
};

// ── A · abertura: a grade dos 10 vídeos se monta ──
const SceneGrade: React.FC<{ t: number; a: number; b: number }> = ({ t, a, b }) => (
  <Cam t={t} a={a} b={b} from={1.0} to={1.08}>
    <div style={{ display: "flex", flexDirection: "column", alignItems: "center" }}>
      <div style={{ display: "grid", gridTemplateColumns: "repeat(5, 152px)", gap: 18 }}>
        {TILES.map((f, i) => {
          const e = sp(t, 0.02 + i * 0.07, 14, 170);
          return (
            <div key={i} style={{ transform: `scale(${e.toFixed(3)}) translateY(${((1 - e) * 60).toFixed(1)}px)`, opacity: Math.min(1, e * 2) }}>
              <Tile f={f} w={152} h={270} from={0} />
            </div>
          );
        })}
      </div>
      <div style={{ marginTop: 80, display: "flex", flexDirection: "column", alignItems: "center" }}>
        <Rise t={t} at={0.13} size={150}>10 VÍDEOS</Rise>
        <Rise t={t} at={0.75} size={112} color={LILAC}>COMERCIAIS</Rise>
      </div>
    </div>
  </Cam>
);

// ── B · o preço contando ──
const ScenePreco: React.FC<{ t: number; a: number; b: number }> = ({ t, a, b }) => {
  const n = Math.round(interpolate(t, [2.25, 3.35], [0, 587], { ...cl, easing: Easing.bezier(0.2, 0.7, 0.3, 1) }));
  const tag = sp(t, a + 0.05, 15, 140);
  return (
    <Cam t={t} a={a} b={b} from={1.05} to={1.0}>
      <div style={{ display: "flex", flexDirection: "column", alignItems: "center" }}>
        <Rise t={t} at={a + 0.05} size={64} weight={700}>por apenas</Rise>
        <div style={{ marginTop: 40, background: BLUE, borderRadius: 40, padding: "40px 60px 50px", display: "flex", alignItems: "flex-start", transform: `rotate(${(-3 * tag).toFixed(2)}deg) scale(${(0.6 + 0.4 * tag).toFixed(3)})`, opacity: Math.min(1, tag * 2), boxShadow: "0 30px 90px rgba(47,61,255,0.5)" }}>
          <div style={{ fontFamily: F, fontWeight: 800, fontSize: 80, color: "#FFFFFF", marginTop: 40, marginRight: 14 }}>R$</div>
          <div style={{ fontFamily: F, fontWeight: 900, fontSize: 280, lineHeight: 1, color: "#FFFFFF", letterSpacing: "-0.04em", fontVariantNumeric: "tabular-nums" }}>{n}</div>
          <div style={{ fontFamily: F, fontWeight: 800, fontSize: 80, color: "#FFFFFF", marginTop: 40, marginLeft: 6 }}>,00</div>
        </div>
        <div style={{ marginTop: 70, display: "flex", gap: 16, alignItems: "center", opacity: k(t, 3.4, 0.4), transform: `translateY(${((1 - k(t, 3.4, 0.5)) * 20).toFixed(1)}px)` }}>
          <div style={{ fontFamily: F, fontWeight: 800, fontSize: 52, color: LILAC, letterSpacing: "0.06em" }}>PELOS 10 VÍDEOS</div>
        </div>
      </div>
    </Cam>
  );
};

// ── C · a conta: 10 vídeos → R$ 58,70 cada ──
const SceneConta: React.FC<{ t: number; a: number; b: number }> = ({ t, a, b }) => {
  const price = sp(t, 9.95, 15, 150);
  const lift = sp(t, 10.9, 18, 120);  // segunda batida: a grade sobe e o preço cresce
  return (
    <Cam t={t} a={a} b={b} from={1.14} to={1.0}>
      <div style={{ display: "flex", flexDirection: "column", alignItems: "center" }}>
        <Rise t={t} at={7.69} size={60} weight={700}>Isso mesmo: são</Rise>
        <div style={{ marginTop: 40, display: "grid", gridTemplateColumns: "repeat(5, 140px)", gap: 16, transform: `translateY(${(-40 * lift).toFixed(1)}px) scale(${(1 - 0.12 * lift).toFixed(3)})` }}>
          {TILES.map((f, i) => {
            const e = sp(t, 8.8 + i * 0.07, 14, 170);
            return (
              <div key={i} style={{ position: "relative", transform: `scale(${e.toFixed(3)})`, opacity: Math.min(1, e * 2) }}>
                <Tile f={f} w={140} h={248} from={a} />
                <div style={{ position: "absolute", left: 10, top: 10, width: 46, height: 46, borderRadius: 23, background: BLUE, display: "flex", alignItems: "center", justifyContent: "center", fontFamily: F, fontWeight: 900, fontSize: 24, color: "#FFFFFF" }}>{i + 1}</div>
              </div>
            );
          })}
        </div>
        <div style={{ marginTop: 50, transform: `translateY(${(-50 * lift).toFixed(1)}px)` }}><Rise t={t} at={9.59} size={60} weight={700}>vídeos por</Rise></div>
        <div style={{ marginTop: 10, display: "flex", alignItems: "flex-start", transformOrigin: "50% 0%", transform: `translateY(${(-40 * lift).toFixed(1)}px) scale(${(0.7 + 0.3 * price + 0.18 * lift).toFixed(3)})`, opacity: Math.min(1, price * 2) }}>
          <div style={{ fontFamily: F, fontWeight: 800, fontSize: 64, color: LILAC, marginTop: 30, marginRight: 12 }}>R$</div>
          <div style={{ fontFamily: F, fontWeight: 900, fontSize: 200, lineHeight: 1, color: LILAC, letterSpacing: "-0.03em" }}>58,70</div>
        </div>
        <div style={{ marginTop: 26, transform: `translateY(${(10 * lift).toFixed(1)}px) scale(${sp(t, 11.9, 12, 170).toFixed(3)})` }}>
          <div style={{ background: BLUE, borderRadius: 999, padding: "14px 48px", fontFamily: F, fontWeight: 900, fontSize: 60, color: "#FFFFFF", letterSpacing: "0.06em" }}>CADA</div>
        </div>
      </div>
    </Cam>
  );
};

// ── D · post nas redes ──
const ScenePost: React.FC<{ t: number; a: number; b: number }> = ({ t, a, b }) => {
  const card = sp(t, a + 0.02, 17, 130);
  const icons: [string[], number][] = [[I_HEART, 18.3], [I_CHAT, 18.5], [I_SEND, 18.7]];
  return (
    <Cam t={t} a={a} b={b} from={1.0} to={1.05}>
      <div style={{ display: "flex", flexDirection: "column", alignItems: "center" }}>
        <div style={{ width: 760, borderRadius: 40, background: PANEL, border: "2px solid rgba(174,184,255,0.3)", overflow: "hidden", transform: `translateY(${((1 - card) * 300).toFixed(1)}px) rotate(${((1 - card) * 5).toFixed(2)}deg)`, opacity: Math.min(1, card * 2) }}>
          <div style={{ display: "flex", alignItems: "center", gap: 20, padding: "26px 30px" }}>
            <div style={{ width: 70, height: 70, borderRadius: 35, background: BLUE }} />
            <div style={{ display: "flex", flexDirection: "column", gap: 10 }}>
              <div style={{ width: 260, height: 18, borderRadius: 9, background: "rgba(255,255,255,0.8)" }} />
              <div style={{ width: 170, height: 14, borderRadius: 7, background: "rgba(174,184,255,0.45)" }} />
            </div>
          </div>
          <div style={{ width: 760, height: 760, overflow: "hidden" }}>
            <Sequence from={Math.round(a * AROF_FPS)} layout="none">
              <OffthreadVideo src={staticFile("ar-estudio/c12.mp4")} muted style={{ width: "100%", height: "100%", objectFit: "cover", objectPosition: "50% 45%" }} />
            </Sequence>
          </div>
          <div style={{ display: "flex", gap: 34, padding: "26px 32px" }}>
            {icons.map(([d, at], i) => (
              <div key={i} style={{ transform: `scale(${sp(t, at, 10, 180).toFixed(3)})` }}><Ico d={d} size={64} color={i === 0 ? RED : "#FFFFFF"} fill={i === 0} sw={2.2} /></div>
            ))}
          </div>
        </div>
        <div style={{ marginTop: 60, display: "flex", flexDirection: "column", alignItems: "center" }}>
          <Rise t={t} at={17.77} size={56} weight={700}>para divulgar a sua empresa</Rise>
          <Rise t={t} at={18.82} size={80} color={LILAC}>NAS REDES SOCIAIS</Rise>
        </div>
      </div>
    </Cam>
  );
};

// ── E · "No pacote": três ícones ──
const ScenePacote: React.FC<{ t: number; a: number; b: number }> = ({ t, a, b }) => (
  <Cam t={t} a={a} b={b} from={1.06} to={1.0}>
    <div style={{ display: "flex", flexDirection: "column", alignItems: "center" }}>
      <Rise t={t} at={20.64} size={170}>NO</Rise>
      <Rise t={t} at={20.74} size={170} color={LILAC}>PACOTE</Rise>
      <div style={{ marginTop: 90, display: "flex", gap: 50 }}>
        {[I_DOC, I_CAM, I_CUT].map((d, i) => {
          const e = sp(t, 21.0 + i * 0.16, 11, 170);
          return (
            <div key={i} style={{ width: 210, height: 210, borderRadius: 105, background: BLUE, display: "flex", alignItems: "center", justifyContent: "center", transform: `scale(${e.toFixed(3)})`, boxShadow: "0 0 60px rgba(47,61,255,0.45)" }}>
              <Ico d={d} size={104} sw={1.9} />
            </div>
          );
        })}
      </div>
    </div>
  </Cam>
);

// ── F/G · as 10 vagas ──
const Vagas: React.FC<{ t: number; at: number; pick?: number; size?: number }> = ({ t, at, pick, size = 140 }) => (
  <div style={{ display: "grid", gridTemplateColumns: `repeat(5, ${size}px)`, gap: 20 }}>
    {Array.from({ length: 10 }, (_, i) => {
      const e = sp(t, at + i * 0.05, 13, 170);
      const p = pick !== undefined && i === 6 ? sp(t, pick, 12, 160) : 0;
      return (
        <div key={i} style={{ width: size, height: size, borderRadius: 28, border: `4px solid ${p > 0.5 ? BLUE : "rgba(174,184,255,0.55)"}`, background: p > 0 ? `rgba(47,61,255,${p.toFixed(3)})` : "rgba(16,21,74,0.6)", display: "flex", alignItems: "center", justifyContent: "center", transform: `scale(${(e * (1 + 0.12 * p)).toFixed(3)})`, boxShadow: p > 0 ? `0 0 ${(60 * p).toFixed(0)}px rgba(47,61,255,0.7)` : undefined, zIndex: p > 0 ? 2 : 1 }}>
          {p > 0.4 ? <Ico d={I_CHECK} size={size * 0.55} sw={3} /> : <div style={{ fontFamily: F, fontWeight: 900, fontSize: size * 0.42, color: "#FFFFFF" }}>{i + 1}</div>}
        </div>
      );
    })}
  </div>
);
const SceneAtencao: React.FC<{ t: number; a: number; b: number }> = ({ t, a, b }) => {
  const chip = sp(t, 28.86, 12, 170);
  return (
    <Cam t={t} a={a} b={b} from={1.14} to={1.0}>
      <div style={{ display: "flex", flexDirection: "column", alignItems: "center" }}>
        <div style={{ transform: `scale(${chip.toFixed(3)})`, background: RED, borderRadius: 999, padding: "18px 50px", fontFamily: F, fontWeight: 900, fontSize: 64, color: "#FFFFFF", letterSpacing: "0.08em" }}>ATENÇÃO</div>
        <div style={{ marginTop: 50 }}><Rise t={t} at={30.02} size={58} weight={700}>essa condição é só para</Rise></div>
        <div style={{ marginTop: 50 }}><Vagas t={t} at={31.1} /></div>
        <div style={{ marginTop: 60, display: "flex", flexDirection: "column", alignItems: "center" }}>
          <Rise t={t} at={31.53} size={128}>10 EMPRESAS</Rise>
          <Rise t={t} at={32.39} size={76} color={LILAC}>DE ÁGUAS CLARAS</Rise>
        </div>
      </div>
    </Cam>
  );
};
const SceneSelecionadas: React.FC<{ t: number; a: number; b: number }> = ({ t, a, b }) => (
  <Cam t={t} a={a} b={b} from={1.05} to={1.0}>
    <div style={{ display: "flex", flexDirection: "column", alignItems: "center" }}>
      <Rise t={t} at={37.19} size={70} weight={800}>SUA EMPRESA PODE SER</Rise>
      <div style={{ marginTop: 60 }}><Vagas t={t} at={a} pick={38.61} size={150} /></div>
      <div style={{ marginTop: 70, display: "flex", flexDirection: "column", alignItems: "center" }}>
        <Rise t={t} at={38.19} size={120}>UMA DAS 10</Rise>
        <Rise t={t} at={38.87} size={104} color={LILAC}>SELECIONADAS</Rise>
      </div>
    </div>
  </Cam>
);

// ── H · final ──
const FLOOD = 39.9;
const Final: React.FC<{ t: number }> = ({ t }) => {
  if (t < FLOOD) return null;
  const r = k(t, FLOOD, 0.6, IN_OUT) * 160;
  const brand = sp(t, FLOOD + 0.12, 18, 120);
  const chip = sp(t, 40.5, 15, 150);
  const btn = sp(t, 41.5, 14, 150);
  const push = 1 + 0.035 * k(t, FLOOD, END - FLOOD, Easing.linear);
  return (
    <AbsoluteFill style={{ clipPath: `circle(${r.toFixed(1)}% at 50% 60%)`, background: `radial-gradient(ellipse 80% 45% at 50% 0%, #1B2380 0%, ${NAVY} 70%)` }}>
      <AbsoluteFill style={{ alignItems: "center", justifyContent: "center", transform: `scale(${push.toFixed(4)})` }}>
        <div style={{ display: "flex", flexDirection: "column", alignItems: "center", width: COL }}>
          <div style={{ overflow: "hidden" }}>
            <div style={{ fontFamily: F, fontWeight: 900, fontSize: 108, lineHeight: 1.05, letterSpacing: "-0.02em", color: "#FFFFFF", whiteSpace: "nowrap", transform: `translateY(${((1 - brand) * 105).toFixed(1)}%)` }}>
              AR <span style={{ color: LILAC }}>ESTÚDIO</span>
            </div>
          </div>
          <div style={{ marginTop: 60, transform: `scale(${chip.toFixed(3)})`, display: "flex", alignItems: "center", gap: 24, border: "3px solid rgba(174,184,255,0.6)", borderRadius: 28, padding: "24px 40px" }}>
            <div style={{ fontFamily: F, fontWeight: 900, fontSize: 64, color: "#FFFFFF" }}>10 VÍDEOS</div>
            <div style={{ width: 4, height: 64, background: "rgba(174,184,255,0.6)" }} />
            <div style={{ fontFamily: F, fontWeight: 900, fontSize: 64, color: LILAC }}>R$ 587</div>
          </div>
          <div style={{ marginTop: 90 }}><Rise t={t} at={40.06} size={60} weight={700}>Entre em contato agora e</Rise></div>
          <div style={{ marginTop: 28, transform: `scale(${(0.5 + 0.5 * btn).toFixed(3)})`, opacity: Math.min(1, btn * 2) }}>
            <div style={{ background: BLUE, borderRadius: 999, padding: "36px 70px", fontFamily: F, fontWeight: 900, fontSize: 66, color: "#FFFFFF", letterSpacing: "0.01em", whiteSpace: "nowrap", boxShadow: "0 20px 60px rgba(47,61,255,0.55)" }}>
              RESERVE SUA VAGA
            </div>
          </div>
          <div style={{ marginTop: 70, display: "flex", alignItems: "center", gap: 14, opacity: k(t, 42.6, 0.5) }}>
            <Ico d={I_PIN} size={46} color={LILAC} fill />
            <div style={{ fontFamily: F, fontWeight: 700, fontSize: 46, color: LILAC }}>Quadra 301 · Águas Claras</div>
          </div>
        </div>
      </AbsoluteFill>
    </AbsoluteFill>
  );
