type Band = { at: number; out: number; lines: string[] };
type Phrase = { a: number; out: number; top?: [string, number]; bands: Band[]; pin?: number; dots?: boolean };
const PH: Phrase[] = [
  { a: 4.15, out: 7.4, top: ["Exclusivo para empresas de", 4.19], bands: [{ at: 6.6, out: 99, lines: ["ÁGUAS CLARAS"] }], pin: 6.45 },
  {
