    bands: [{ at: 14.33, out: 15.2, lines: ["DINÂMICA"] }, { at: 15.28, out: 16.22, lines: ["CRIATIVA"] }, { at: 16.45, out: 99, lines: ["PROFISSIONAL"] }],
  },
  {
    a: 22.45, out: 28.65, top: ["Incluso no pacote:", 22.4], dots: true,
    bands: [{ at: 22.5, out: 23.75, lines: ["CRIAÇÃO DOS", "ROTEIROS"] }, { at: 23.84, out: 25.8, lines: ["CAPTAÇÃO", "PROFISSIONAL"] }, { at: 25.9, out: 27.2, lines: ["EDIÇÃO", "COMPLETA"] }, { at: 27.26, out: 99, lines: ["PRONTA PARA", "PUBLICAR"] }],
  },
  {
    a: 33.6, out: 36.85, top: ["para garantir a", 33.59],
    bands: [{ at: 34.23, out: 35.25, lines: ["QUALIDADE"] }, { at: 35.36, out: 99, lines: ["E O CUIDADO COM", "CADA VÍDEO"] }],
  },
];
const fit = (lines: string[], max: number) => Math.min(max, Math.floor((COL - 70) / (Math.max(...lines.map((l) => l.length)) * 0.74)));

const BandBox: React.FC<{ t: number; b: Band }> = ({ t, b }) => {
  const size = fit(b.lines, 108);
  const w = k(t, b.at - 0.04, 0.38, IN_OUT);
  const o = k(t, b.out, 0.12, Easing.linear);
  if (t < b.at - 0.05 || o >= 1) return null;
  return (
    <div style={{ position: "absolute", left: 0, right: 0, top: 0, display: "flex", justifyContent: "center", opacity: 1 - o }}>
      <div style={{ background: BLUE, padding: `${Math.round(size * 0.2)}px ${Math.round(size * 0.36)}px`, borderRadius: 14, clipPath: `inset(0 ${((1 - w) * 100).toFixed(2)}% 0 0 round 14px)`, boxShadow: "0 18px 50px rgba(20,30,180,0.45)" }}>
        {b.lines.map((l, i) => {
          const e = sp(t, b.at + 0.06 + i * 0.1, 20, 140);
          return (
            <div key={i} style={{ overflow: "hidden", textAlign: "center" }}>
              <div style={{ fontFamily: F, fontWeight: 900, fontSize: size, lineHeight: 1.08, letterSpacing: "-0.01em", color: "#FFFFFF", whiteSpace: "nowrap", transform: `translateY(${((1 - e) * 105).toFixed(1)}%)` }}>{l}</div>
            </div>
          );
        })}
      </div>
    </div>
  );
};

const Lettering: React.FC<{ t: number }> = ({ t }) => (
  <>
    {PH.map((p, i) => {
      if (t < p.a - 0.1 || t > p.out + 0.2) return null;
      const o = k(t, p.out, 0.16, Easing.linear);
      const topE = p.top ? sp(t, Math.max(p.top[1], p.a), 20, 140) : 0;
      const pin = p.pin !== undefined ? sp(t, p.pin, 11, 160) : 0;
      return (
        <div key={i} style={{ position: "absolute", left: 120, right: 120, top: 1200, height: 520, display: "flex", flexDirection: "column", alignItems: "center", opacity: 1 - o, filter: o > 0 ? `blur(${(o * 10).toFixed(1)}px)` : undefined }}>
          {p.pin !== undefined ? (
            <div style={{ position: "absolute", top: -150, transform: `translateY(${((1 - pin) * -120).toFixed(1)}px)`, opacity: Math.min(1, pin * 3) }}>
              <div style={{ width: 110, height: 110, borderRadius: 55, background: BLUE, display: "flex", alignItems: "center", justifyContent: "center", boxShadow: "0 10px 40px rgba(47,61,255,0.6)" }}><Ico d={I_PIN} size={62} fill /></div>
            </div>
          ) : null}
          {p.top ? (
            <div style={{ overflow: "hidden", marginBottom: 22 }}>
              <div style={{ fontFamily: F, fontWeight: 700, fontSize: 58, lineHeight: 1.15, color: "#FFFFFF", whiteSpace: "nowrap", textShadow: "0 3px 16px rgba(0,0,0,0.6)", transform: `translateY(${((1 - topE) * 105).toFixed(1)}%)` }}>{p.top[0]}</div>
            </div>
          ) : null}
          <div style={{ position: "relative", width: COL, flex: 1 }}>
            {p.bands.map((b, j) => <BandBox key={j} t={t} b={b} />)}
          </div>
          {p.dots ? (
            <div style={{ position: "absolute", bottom: 40, display: "flex", gap: 14 }}>
              {p.bands.map((b, j) => (
                <div key={j} style={{ width: 64, height: 5, borderRadius: 3, background: "rgba(255,255,255,0.25)" }}>
                  <div style={{ width: "100%", height: "100%", borderRadius: 3, background: "#FFFFFF", transformOrigin: "0 50%", transform: `scaleX(${k(t, b.at, 0.6, IN_OUT)})` }} />
                </div>
              ))}
            </div>
          ) : null}
        </div>
      );
    })}
  </>
);

export const ArEstudioOferta: React.FC = () => {
  const t = useCurrentFrame() / AROF_FPS;
  return (
    <AbsoluteFill style={{ background: NAVY }}>
      {LAYERS.map((L, i) => {
        if (t < L.a || t >= L.b + 0.6) return null;
        const next = LAYERS[i + 1];
        if (next && t >= next.a + 0.6) return null;
        return (
          <Frame key={i} t={t} L={L}>
            {L.M ? <L.M t={t} a={L.a} b={L.b} /> : <Footage t={t} L={L} />}
          </Frame>
        );
      })}
      <Lettering t={t} />
      <Final t={t} />
    </AbsoluteFill>
  );
};

